export function normalEdges(data,w,h,strength=50,thickness=1){const mask=new Uint8Array(w*h),threshold=15+(100-strength)*1.45;for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){const i=(y*w+x)*4;let edge=0;for(let c=0;c<3;c++)edge=Math.max(edge,Math.abs(data[i+4+c]-data[i-4+c]),Math.abs(data[i+w*4+c]-data[i-w*4+c]));if(edge>threshold)mask[y*w+x]=1;}return thickenEdges(mask,w,h,thickness);}
